<?php $pageTitle='Edit Grease Trap';require 'includes/header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){flash('error','Invalid trap.');header('Location: traps.php');exit;}$q=$pdo->prepare("SELECT * FROM grease_traps WHERE id=?");$q->execute([$id]);$t=$q->fetch();if(!$t){flash('error','Trap not found.');header('Location: traps.php');exit;}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$loc=trim($_POST['location']??'');$last=$_POST['last_cleaned_date']??'';$int=$_POST['cleaning_interval']??'';if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??''))$errors[]='Invalid form submission.';if($loc==='')$errors[]='Location is required.';if($last==='')$errors[]='Last cleaned date is required.';if(!ctype_digit((string)$int)||(int)$int<1)$errors[]='Cleaning interval must be positive.';if(!$errors){$q=$pdo->prepare("UPDATE grease_traps SET location=?,last_cleaned_date=?,cleaning_interval=? WHERE id=?");$q->execute([$loc,$last,(int)$int,$id]);flash('success','Grease trap updated successfully.');header('Location: traps.php');exit;}$t['location']=$loc;$t['last_cleaned_date']=$last;$t['cleaning_interval']=$int;}?>
<section class="form-panel"><h3>Edit <?=h($t['trap_code'])?></h3><p>Update the trap schedule.</p><?php if($errors):?><div class="errors"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?>
<form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><label>Trap Code<input value="<?=h($t['trap_code'])?>" disabled></label><label>Location<input name="location" required value="<?=h($t['location'])?>"></label><label>Last Cleaned Date<input type="date" name="last_cleaned_date" required value="<?=h($t['last_cleaned_date'])?>"></label><label>Cleaning Interval (days)<input type="number" name="cleaning_interval" min="1" required value="<?=h((string)$t['cleaning_interval'])?>"></label><div class="actions"><a class="btn secondary" href="traps.php">Cancel</a><button class="btn primary">Update Trap</button></div></form></section><?php require 'includes/footer.php';?>